"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { MapMarker } from "@/components/map-marker"
import { Plus, Minus, Locate, Layers } from "lucide-react"

interface MapLocation {
  id: string
  name: string
  lat: number
  lng: number
  type: "destination" | "food" | "event" | "hotel" | "attraction"
}

const mockLocations: MapLocation[] = [
  { id: "1", name: "Eiffel Tower", lat: 48.8584, lng: 2.2945, type: "attraction" },
  { id: "2", name: "Le Petit Bistro", lat: 48.8566, lng: 2.3522, type: "food" },
  { id: "3", name: "Grand Hotel Paris", lat: 48.869, lng: 2.332, type: "hotel" },
  { id: "4", name: "Louvre Museum", lat: 48.8606, lng: 2.3376, type: "attraction" },
  { id: "5", name: "Jazz Festival", lat: 48.8738, lng: 2.295, type: "event" },
  { id: "6", name: "Notre-Dame", lat: 48.853, lng: 2.3499, type: "destination" },
]

interface InteractiveMapProps {
  onMarkerClick?: (location: MapLocation) => void
  selectedId?: string
}

export function InteractiveMap({ onMarkerClick, selectedId }: InteractiveMapProps) {
  const [zoom, setZoom] = useState(100)

  const handleZoomIn = () => setZoom((prev) => Math.min(prev + 20, 200))
  const handleZoomOut = () => setZoom((prev) => Math.max(prev - 20, 50))

  return (
    <div className="relative w-full h-full bg-secondary/20 overflow-hidden">
      {/* Mock map background */}
      <div
        className="absolute inset-0 transition-transform duration-300"
        style={{
          transform: `scale(${zoom / 100})`,
          backgroundImage: `url('/world-map-abstract-dots-pattern-light.jpg')`,
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        {/* Map grid overlay */}
        <div
          className="absolute inset-0 opacity-10"
          style={{
            backgroundImage: `
              linear-gradient(to right, currentColor 1px, transparent 1px),
              linear-gradient(to bottom, currentColor 1px, transparent 1px)
            `,
            backgroundSize: "50px 50px",
          }}
        />

        {/* Map markers */}
        {mockLocations.map((location) => (
          <div
            key={location.id}
            className="absolute transform -translate-x-1/2 -translate-y-1/2 transition-all"
            style={{
              left: `${30 + (location.lng - 2.2) * 200}%`,
              top: `${70 - (location.lat - 48.85) * 500}%`,
            }}
          >
            <MapMarker
              type={location.type}
              selected={selectedId === location.id}
              onClick={() => onMarkerClick?.(location)}
            />
          </div>
        ))}
      </div>

      {/* Map controls */}
      <div className="absolute right-4 top-4 flex flex-col gap-2">
        <Button variant="secondary" size="icon" onClick={handleZoomIn} className="shadow-lg">
          <Plus className="h-4 w-4" />
        </Button>
        <Button variant="secondary" size="icon" onClick={handleZoomOut} className="shadow-lg">
          <Minus className="h-4 w-4" />
        </Button>
        <div className="h-px bg-border my-1" />
        <Button variant="secondary" size="icon" className="shadow-lg">
          <Locate className="h-4 w-4" />
        </Button>
        <Button variant="secondary" size="icon" className="shadow-lg">
          <Layers className="h-4 w-4" />
        </Button>
      </div>

      {/* Zoom level indicator */}
      <div className="absolute left-4 bottom-4 px-3 py-1.5 bg-background/80 backdrop-blur-sm rounded-full text-sm">
        Zoom: {zoom}%
      </div>

      {/* Legend */}
      <div className="absolute right-4 bottom-4 p-3 bg-background/80 backdrop-blur-sm rounded-lg text-xs space-y-1.5">
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-full bg-primary" />
          <span>Destinations</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-full bg-accent" />
          <span>Food</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-full bg-chart-3" />
          <span>Events</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded-full bg-chart-4" />
          <span>Hotels</span>
        </div>
      </div>
    </div>
  )
}
