// Mock data for the Indian Travel Companion app

// TypeScript Types
export type Region = 'North' | 'South' | 'East' | 'West' | 'Central' | 'Northeast';
export type Category = 'Spiritual' | 'Adventure' | 'Heritage' | 'Nature' | 'Beach' | 'Hill Station' | 'Wildlife';
export type Season = 'Summer' | 'Winter' | 'Monsoon' | 'Spring' | 'Autumn';

export interface Weather {
  temperature: number;
  condition: string;
  humidity: number;
  bestTimeToVisit: string;
}

export interface Place {
  id: string;
  name: string;
  location: string;
  state: string;
  region: Region;
  category: Category[];
  description: string;
  shortDescription: string;
  image: string;
  images: string[];
  rating: number;
  reviewCount: number;
  price: string;
  duration: string;
  bestSeason: Season[];
  weather: Weather;
  highlights: string[];
  activities: string[];
  nearbyAttractions: string[];
  coordinates: { lat: number; lng: number };
  monthlyVisitors: number;
  featured: boolean;
}

export interface TravelBuddy {
  id: string;
  name: string;
  avatar: string;
  location: string;
  interests: Category[];
  upcomingTrip: string;
  bio: string;
}

export interface MonthlyVisitorData {
  month: string;
  visitors: number;
}

