"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Sun, Cloud, CloudRain, CloudSnow, Wind, Droplets, Thermometer } from "lucide-react"

interface WeatherData {
  location: string
  temp: number
  condition: "sunny" | "cloudy" | "rainy" | "snowy"
  humidity: number
  windSpeed: number
  feelsLike: number
  forecast: {
    day: string
    temp: number
    condition: "sunny" | "cloudy" | "rainy" | "snowy"
  }[]
}

const weatherIcons = {
  sunny: Sun,
  cloudy: Cloud,
  rainy: CloudRain,
  snowy: CloudSnow,
}

interface WeatherWidgetProps {
  data?: WeatherData
  compact?: boolean
}

const defaultWeather: WeatherData = {
  location: "Paris, France",
  temp: 18,
  condition: "sunny",
  humidity: 65,
  windSpeed: 12,
  feelsLike: 16,
  forecast: [
    { day: "Mon", temp: 18, condition: "sunny" },
    { day: "Tue", temp: 20, condition: "sunny" },
    { day: "Wed", temp: 17, condition: "cloudy" },
    { day: "Thu", temp: 15, condition: "rainy" },
    { day: "Fri", temp: 16, condition: "cloudy" },
    { day: "Sat", temp: 19, condition: "sunny" },
    { day: "Sun", temp: 21, condition: "sunny" },
  ],
}

export function WeatherWidget({ data = defaultWeather, compact = false }: WeatherWidgetProps) {
  const WeatherIcon = weatherIcons[data.condition]

  if (compact) {
    return (
      <div className="flex items-center gap-3 p-3 bg-secondary/50 rounded-lg">
        <WeatherIcon className="h-8 w-8 text-accent" />
        <div>
          <p className="text-xl font-bold">{data.temp}°C</p>
          <p className="text-xs text-muted-foreground capitalize">{data.condition}</p>
        </div>
      </div>
    )
  }

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-lg flex items-center justify-between">
          <span>Weather</span>
          <span className="text-sm font-normal text-muted-foreground">{data.location}</span>
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="flex items-center gap-4 mb-4">
          <WeatherIcon className="h-16 w-16 text-accent" />
          <div>
            <p className="text-4xl font-bold">{data.temp}°C</p>
            <p className="text-muted-foreground capitalize">{data.condition}</p>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-4 mb-4 p-3 bg-secondary/30 rounded-lg">
          <div className="flex items-center gap-2">
            <Thermometer className="h-4 w-4 text-muted-foreground" />
            <div>
              <p className="text-xs text-muted-foreground">Feels Like</p>
              <p className="font-medium">{data.feelsLike}°C</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Droplets className="h-4 w-4 text-muted-foreground" />
            <div>
              <p className="text-xs text-muted-foreground">Humidity</p>
              <p className="font-medium">{data.humidity}%</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Wind className="h-4 w-4 text-muted-foreground" />
            <div>
              <p className="text-xs text-muted-foreground">Wind</p>
              <p className="font-medium">{data.windSpeed} km/h</p>
            </div>
          </div>
        </div>

        <div>
          <p className="text-sm font-medium mb-2">7-Day Forecast</p>
          <div className="grid grid-cols-7 gap-1">
            {data.forecast.map((day) => {
              const DayIcon = weatherIcons[day.condition]
              return (
                <div key={day.day} className="text-center p-2 rounded-lg hover:bg-secondary/50 transition-colors">
                  <p className="text-xs text-muted-foreground mb-1">{day.day}</p>
                  <DayIcon className="h-4 w-4 mx-auto text-muted-foreground" />
                  <p className="text-sm font-medium mt-1">{day.temp}°</p>
                </div>
              )
            })}
          </div>
        </div>
      </CardContent>
    </Card>
  )
}
